1	import { readdirSync, readFileSync, existsSync } from 'node:fs';
2	import { join, dirname } from 'node:path';
3	import { fileURLToPath } from 'node:url';
4	import { loadPacks, resolveDeclaredPacks, packEntryId, SHARED_SUBDIR, PACK_DIRECTORY_FILE } from '../engine/pack_loader/pack-registry.mjs';
5	import { relativeImports, resolveRelative, ENGINE_DIR_ROOTS } from '../engine/checks/helpers/module-imports.mjs';
6	import { recordDirIsRecent } from '../engine/checks/helpers/active-migrations.mjs';
7	
8	// The vendor-set computation for the vendored mount (DESIGN.md): given a repo's
9	// pack declaration, the minimal corpus file set that repo persists under
10	// SHARED_SUBDIR — canon-relative paths, mirroring exactly what a future
11	// submodule mounted at that same root would place there. Always computed
12	// against the canon tree THIS module ships in — the nightly runs it from the
13	// home checkout, an on-demand refresh from the tree it just fetched — so the
14	// set and the content can never come from different snapshots.
15	const canonRoot = dirname(dirname(fileURLToPath(import.meta.url))); // <canon>/vendoring/ — canon-internal, never vendored (#385)
16	
17	// Re-exported for the writers (the nightly update pass, an on-demand refresh):
18	// the consumer-side root the set materializes under.
19	export { SHARED_SUBDIR };
20	
21	// The engine is discovered structurally, never listed file-by-file: the engine
22	// root vendors wholesale (a new engine file ships with no edit here). The list
23	// lives in the engine lib (engine/checks/helpers/module-imports.mjs) — the same
24	// surface the pack-independence barrier confines pack imports to, so "what a
25	// pack may import" and "what every consumer carries" can never drift apart —
26	// re-exported here as the vendor-set contract (DESIGN.md). engine/ carries no
27	// tests (they live in engine-tests/, mirroring its structure — #385), so the
28	// engine walk is a plain copy minus *.md — engine docs are canon-maintainer
29	// reference, read upstream when needed, while a pack's .md files are the
30	// payload and ride its directory below (pack tests live in packs-tests/, not in packs/).
31	export { ENGINE_DIR_ROOTS };
32	
33	const isTest = (name) => name.endsWith('.test.mjs');
34	
35	// The exception to "engine .md is maintainer-reference, not vendored": a few engine
36	// .md files are OPERATIONAL — a consumer session reads them from its OWN mount at
37	// runtime, so they MUST ship. `executor.md` is the executor routine's operating
38	// instructions; the label-wired routine's thin-pointer prompt points at
39	// `.claudinite/shared/engine/scheduler/executor.md`, so if it is stripped, every
40	// consumer's executor session boots with no instructions and can drain nothing
41	// (the fleet-wide executor-broken finding). `deliver-pr.md` is the agent-lane
42	// delivery procedure the merged-pr task worker files link to — stripped, every
43	// such task.md points at a hole and the subagent improvises its own landing.
44	// Whitelisted by canon-relative path so the blanket .md exclusion still drops
45	// the maintainer docs beside them.
46	const VENDORED_ENGINE_DOCS = new Set(['engine/scheduler/executor.md', 'engine/scheduler/deliver-pr.md']);
47	
48	// The migration machinery a consumer applies from its OWN mount (task-prework
49	// DESIGN §7): the applier + registry + the RECENT record folders, so baselining
50	// reads the notes locally and needs no canon checkout in session. Not the README.
51	// All records live flat under migrations/ as <landed-date>-<slug>/ folders, and
52	// FETCHING decides relevance: only the folders landed within the recency window
53	// (recordDirIsRecent, the same predicate migrationActive tolerates by) ship in a
54	// mount — an up-to-date consumer carries few-to-none, and a dormant project
55	// catches up from the fresh canon clone baselining fetches, where every record
56	// ever landed is present. Vendoring these also activates `migrationActive()`
57	// legacy-tolerance in consumer checks — a check tolerates a legacy shape while
58	// its migration is recent.
59	const MIGRATIONS_ROOT = 'migrations';
60	const VENDORED_MIGRATION_MODULES = ['apply.mjs', 'registry.mjs'];
61	function walkMigrations(files, errors, today) {
62	  for (const name of VENDORED_MIGRATION_MODULES) {
63	    if (existsSync(join(canonRoot, MIGRATIONS_ROOT, name))) files.add(`${MIGRATIONS_ROOT}/${name}`);
64	    else errors.push({ what: `${MIGRATIONS_ROOT}/${name} is missing from the canon tree`, fix: `restore ${MIGRATIONS_ROOT}/${name}` });
65	  }
66	  let entries;
67	  try {
68	    entries = readdirSync(join(canonRoot, MIGRATIONS_ROOT), { withFileTypes: true });
69	  } catch (e) {
70	    errors.push({ what: `${MIGRATIONS_ROOT} is not a readable directory in the canon tree: ${e.message}`, fix: `restore ${MIGRATIONS_ROOT}` });
71	    return;
72	  }
73	  for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
74	    if (entry.isDirectory() && isRecordDir(entry.name) && recordDirIsRecent(entry.name, today)) {
75	      walk(`${MIGRATIONS_ROOT}/${entry.name}`, files, errors);
76	    }
77	  }
78	}
79	const isRecordDir = (name) => /^\d{4}-\d{2}-\d{2}-/.test(name);
80	
81	function walk(relDir, files, errors, { engine = false } = {}) {
82	  let entries;
83	  try {
84	    entries = readdirSync(join(canonRoot, relDir), { withFileTypes: true });
85	  } catch (e) {
86	    errors.push({
87	      what: `${relDir} is not a readable directory in the canon tree: ${e.message}`,
88	      fix: `restore ${relDir}, or fix what names it (an engine root, a pack.mjs skills list)`,
89	    });
90	    return;
91	  }
92	  for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
93	    if (entry.isDirectory()) {
94	      if (engine && entry.name === 'test') continue;
95	      walk(`${relDir}/${entry.name}`, files, errors, { engine });
96	    } else if (!isTest(entry.name)) {
97	      const rel = `${relDir}/${entry.name}`;
98	      // engine .md is canon-maintainer reference and dropped — except the
99	      // operational whitelist (executor.md) a consumer reads from its own mount.
100	      if (engine && entry.name.endsWith('.md') && !VENDORED_ENGINE_DOCS.has(rel)) continue;
101	      files.add(rel);
102	    }
103	  }
104	}
105	
106	// declaredEntries: the raw `packs` array from .claudinite-checks.json (id
107	// strings and/or entry objects). Returns { files, errors }:
108	// sorted canon-relative paths, and { what, fix } diagnostics. Ids naming no
109	// canon pack (a consumer's local packs, or a typo the runner's settings
110	// validation already flags) are skipped without error. A pack's
111	// bundled skills (<pack>/skills/) ride its directory walk — there is no
112	// separate skills collection to union (#385). `today` (YYYY-MM-DD) pins the
113	// migration recency window for a deterministic set; defaults to the wall clock.
114	export async function computeVendorSet(declaredEntries, { today } = {}) {
115	  const files = new Set();
116	  const errors = [];
117	
118	  for (const root of ENGINE_DIR_ROOTS) walk(root, files, errors, { engine: true });
119	  walkMigrations(files, errors, today);
120	
121	  // The full pack directory ships with EVERY mount, whatever the declaration:
122	  // the set otherwise carries only the declared packs, so without this catalog
123	  // a member session has no view of what else it could adopt (#726). Missing
124	  // is canon-side breakage — a mount silently without it would blind the whole
125	  // fleet to the catalog — so it aborts the converge like any other set error.
126	  if (existsSync(join(canonRoot, PACK_DIRECTORY_FILE))) files.add(PACK_DIRECTORY_FILE);
